int WINAPI wWinMain(HINSTANCE instance, HINSTANCE, wchar_t *, int) {
  int result{};
  try {
    EngineConfig config{};
    config.title = L"Aevrynd World Partition Milestone C";
    config.width = 320;
    config.height = 180;
    config.renderQuality = RenderQuality3D::Low;
    config.enableAutomaticMemoryTrim = false;
